"""Calculate cleaning-service salaries by monthly Tuesday billing period."""

from __future__ import annotations

import csv
import json
import re
from bisect import bisect_right
from datetime import date, timedelta
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP
from pathlib import Path


DATA_DIR = Path("/app/dataset")


def _read_csv(name: str) -> list[dict[str, str]]:
    with (DATA_DIR / name).open(newline="", encoding="utf-8-sig") as stream:
        return list(csv.DictReader(stream))


def _first_weekday_of_month(year: int, month: int, weekday: int) -> date:
    first = date(year, month, 1)
    return first + timedelta(days=(weekday - first.weekday()) % 7)


def answer() -> dict[str, list[int]]:
    employees = {
        row["PESEL"]: Decimal(row["hourly_rate"])
        for row in _read_csv("employees.csv")
    }
    task_pay = {
        int(row["task_id"]): Decimal(row["pay_per_completion"])
        for row in _read_csv("tasks.csv")
    }

    shifts: list[tuple[date, str, Decimal, Decimal]] = []
    seen: set[tuple[str, ...]] = set()

    for row in _read_csv("timesheet.csv"):
        pesel = row["employee_id"]
        if pesel not in employees:
            continue

        try:
            work_date = date.fromisoformat(row["date"])
            hours = Decimal(row["hours_worked"])
        except (ValueError, InvalidOperation):
            continue
        if not hours.is_finite() or not 0 <= hours <= 24:
            continue

        # The row ID is unique even for repeated copies of the same shift.
        shift_key = tuple(value for key, value in row.items() if key != "id")
        if shift_key in seen:
            continue
        seen.add(shift_key)

        # The task list has occasional missing brackets and extra unknown IDs.
        # Valid task IDs determine the earned bonus; the stored bonus can be
        # negative or include payments for nonexistent tasks.
        task_ids = (int(number) for number in re.findall(r"\d+", row["performed_tasks"]))
        bonus = sum((task_pay.get(task_id, Decimal(0)) for task_id in task_ids), Decimal(0))
        shifts.append((work_date, pesel, hours, bonus))

    if not shifts:
        return {pesel: [] for pesel in employees}

    first_date = min(shift[0] for shift in shifts)
    last_date = max(shift[0] for shift in shifts)
    weekday = first_date.weekday()

    # Every billing month begins on the first occurrence of the weekday of
    # the earliest shift. Days before the next start belong to the prior month.
    period_starts: list[date] = []
    year, month = first_date.year, first_date.month
    while (year, month) <= (last_date.year, last_date.month):
        period_starts.append(_first_weekday_of_month(year, month, weekday))
        year, month = (year + 1, 1) if month == 12 else (year, month + 1)

    totals = {pesel: [Decimal(0)] * len(period_starts) for pesel in employees}
    for work_date, pesel, hours, bonus in shifts:
        period = bisect_right(period_starts, work_date) - 1
        if period >= 0:
            totals[pesel][period] += hours * employees[pesel] + bonus

    return {
        pesel: [int(value.quantize(Decimal("1"), rounding=ROUND_HALF_UP)) for value in amounts]
        for pesel, amounts in totals.items()
    }


if __name__ == "__main__":
    with open("/app/answer.json", "w", encoding="utf-8") as output:
        json.dump(answer(), output, ensure_ascii=False)

